from math import isqrt

def bay_ledger(bays, operations):
    size = max(1, isqrt(bays - 1) + 1)
    counts = [0] * (bays + 1)
    block_sum = [0] * (bays // size + 1)
    reports = []
    for op in operations:
        if op[0] == 'set':
            block_sum[(op[1] - 1) // size] += op[2] - counts[op[1]]
            counts[op[1]] = op[2]
        elif op[0] == 'total':
            full_blocks = op[1] // size
            total = 0
            for block in range(full_blocks):
                total += block_sum[block]
            for bay in range(full_blocks * size + 1, op[1] + 1):
                total += counts[bay]
            reports.append(total)
        else:
            remaining, block = op[1], 0
            while block * size < bays and block_sum[block] < remaining:
                remaining -= block_sum[block]
                block += 1
            found = -1
            for bay in range(block * size + 1, min(bays, (block + 1) * size) + 1):
                remaining -= counts[bay]
                if remaining <= 0:
                    found = bay
                    break
            reports.append(found)
    return reports

def bay_ledger(bays, operations):
    tree, held = [0] * (bays + 1), [0] * (bays + 1)
    top = 1 << (bays.bit_length() - 1)
    reports = []
    for op in operations:
        if op[0] == 'set':
            change = op[2] - held[op[1]]
            held[op[1]] = op[2]
            at = op[1]
            while at <= bays:
                tree[at] += change
                at += at & -at
        elif op[0] == 'total':
            total, at = 0, op[1]
            while at > 0:
                total += tree[at]
                at -= at & -at
            reports.append(total)
        else:
            at, remaining, step = 0, op[1], top
            while step:
                if at + step <= bays and tree[at + step] < remaining:
                    at += step
                    remaining -= tree[at]
                step >>= 1
            reports.append(at + 1 if at + 1 <= bays else -1)
    return reports

