def booth_bookings(gap, operations):
    horizon = 1000000
    owner = array('i', [0]) * (horizon + 1)
    is_start = bytearray(horizon + 1)
    spans, results = {}, []
    issued = 0
    for op in operations:
        if op[0] == 'book':
            start, end = op[1:]
            clash = False
            for minute in range(max(0, start - gap), min(horizon, end + gap)):
                if owner[minute]:
                    clash = True
                    break
            if clash:
                results.append(-1)
            else:
                issued += 1
                for minute in range(start, end):
                    owner[minute] = issued
                is_start[start] = 1
                spans[issued] = (start, end)
                results.append(issued)
        elif op[0] == 'cancel':
            span = spans.pop(op[1], None)
            if span is None:
                results.append(False)
            else:
                for minute in range(span[0], span[1]):
                    owner[minute] = 0
                is_start[span[0]] = 0
                results.append(True)
        else:
            minute = op[1]
            while minute <= horizon and not is_start[minute]:
                minute += 1
            results.append(minute if minute <= horizon else -1)
    return results

