from heapq import heappop, heappush

def cheapest_route(stops, roads, start, target):
    adjacent = [[] for _ in range(stops)]
    for a, b, toll in roads:
        adjacent[a].append((b, toll))
        adjacent[b].append((a, toll))
    best = [float('inf')] * stops
    best[start] = 0
    heap = [(0, start)]
    while heap:
        toll, stop = heappop(heap)
        if toll > best[stop]:
            continue
        if stop == target:
            return toll
        for neighbor, extra in adjacent[stop]:
            candidate = toll + extra
            if candidate < best[neighbor]:
                best[neighbor] = candidate
                heappush(heap, (candidate, neighbor))
    return -1

def cipher_window(text, pattern):
