    return ''

def cipher_window(text, pattern):
    if not pattern:
        return ''
    need = [0] * 26
    for symbol in pattern:
        need[ord(symbol) - 97] += 1
    missing, left = len(pattern), 0
    best_start, best_length = 0, float('inf')
    for right, symbol in enumerate(text):
        at = ord(symbol) - 97
        if need[at] > 0:
            missing -= 1
        need[at] -= 1
        while missing == 0:
            if right - left + 1 < best_length:
                best_start, best_length = left, right - left + 1
            at = ord(text[left]) - 97
            need[at] += 1
