def crossword_trace(grid, word):
    rows, cols = len(grid), len(grid[0])
    def extend(path):
        if len(path) == len(word):
            return ''.join(grid[r][c] for r, c in path) == word
        r, c = path[-1]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in path:
                if extend(path + [(nr, nc)]):
                    return True
        return False
    return any(extend([(r, c)]) for r in range(rows) for c in range(cols))

def crossword_trace(grid, word):
    rows, cols = len(grid), len(grid[0])
    used = [[False] * cols for _ in range(rows)]
    def walk(r, c, i):
        if not (0 <= r < rows and 0 <= c < cols) or used[r][c] or grid[r][c] != word[i]:
            return False
        if i == len(word) - 1:
            return True
        used[r][c] = True
        found = (walk(r + 1, c, i + 1) or walk(r - 1, c, i + 1)
                 or walk(r, c + 1, i + 1) or walk(r, c - 1, i + 1))
        used[r][c] = False
        return found
    return any(walk(r, c, 0) for r in range(rows) for c in range(cols))

def dial_distance(bits, pairs):
