def elevation_ledger(benchmarks, statements):
    links = [[] for _ in range(benchmarks)]
    results = []
    for a, b, difference in statements:
        height_from_a, stack = {a: 0}, [a]
        while stack:
            at = stack.pop()
            for other, delta in links[at]:
                if other not in height_from_a:
                    height_from_a[other] = height_from_a[at] + delta
                    stack.append(other)
        if b not in height_from_a:
            links[a].append((b, -difference))
            links[b].append((a, difference))
            results.append('new')
        else:
            results.append('known' if height_from_a[b] == -difference else 'conflict')
    return results

def exact_flags(readings, k):
    total = 0
    for start in range(len(readings)):
        flagged = 0
        for end in range(start, len(readings)):
            flagged += readings[end] % 2
            if flagged == k:
                total += 1
    return total

def exact_flags(readings, k):
    seen = [0] * (len(readings) + 1)
    seen[0] = 1
    flagged = total = 0
    for reading in readings:
        flagged += reading % 2
        if flagged >= k:
            total += seen[flagged - k]
        seen[flagged] += 1
    return total

def exact_flags(readings, k):
    def at_most(limit):
        if limit < 0:
            return 0
        left = flagged = stretches = 0
        for right, reading in enumerate(readings):
            flagged += reading % 2
            while flagged > limit:
                flagged -= readings[left] % 2
                left += 1
            stretches += right - left + 1
        return stretches
    return at_most(k) - at_most(k - 1)

def fare_combinations(coins, amount):
    modulus = 1000000007
    def count(index, remaining):
        if remaining == 0:
            return 1
        if index == len(coins):
            return 0
        total = 0
        for quantity in range(remaining // coins[index] + 1):
            total = (total + count(index + 1, remaining - quantity * coins[index])) % modulus
        return total
    return count(0, amount)

def fare_combinations(coins, amount):
    modulus = 1000000007
    ways = [0] * (amount + 1)
    ways[0] = 1
    for coin in coins:
        for total in range(coin, amount + 1):
            ways[total] = (ways[total] + ways[total - coin]) % modulus
    return ways[amount]

def fewest_tokens(tokens, amount):
    def fewest(remaining):
        if remaining == 0:
            return 0
        best = float('inf')
        for token in tokens:
            if token <= remaining:
                best = min(best, 1 + fewest(remaining - token))
        return best
    result = fewest(amount)
    return -1 if result == float('inf') else result

def fewest_tokens(tokens, amount):
    fewest = [float('inf')] * (amount + 1)
    fewest[0] = 0
    for value in range(1, amount + 1):
        for token in tokens:
            if token <= value:
                fewest[value] = min(fewest[value], fewest[value - token] + 1)
    return -1 if fewest[amount] == float('inf') else fewest[amount]

def first_redundant_link(stations, links):
    adjacent = [[] for _ in range(stations)]
    for a, b in links:
        seen, stack = {a}, [a]
        while stack:
            station = stack.pop()
            for neighbor in adjacent[station]:
                if neighbor not in seen:
                    seen.add(neighbor)
                    stack.append(neighbor)
        if b in seen:
            return [a, b]
        adjacent[a].append(b)
        adjacent[b].append(a)
    return []

def first_redundant_link(stations, links):
    parent, size = list(range(stations)), [1] * stations
    def find(station):
        while parent[station] != station:
            parent[station] = parent[parent[station]]
            station = parent[station]
        return station
    for a, b in links:
        root_a, root_b = find(a), find(b)
        if root_a == root_b:
            return [a, b]
        if size[root_a] < size[root_b]:
            root_a, root_b = root_b, root_a
        parent[root_b] = root_a
        size[root_a] += size[root_b]
    return []

from collections import deque

def floodgate_path(grid):
    rows, cols = len(grid), len(grid[0])
    levels = sorted({height for row in grid for height in row})
    for level in levels:
        if grid[0][0] > level:
            continue
        seen, queue = {(0, 0)}, deque([(0, 0)])
        while queue:
            r, c = queue.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if (0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] <= level
                        and (nr, nc) not in seen):
                    seen.add((nr, nc))
                    queue.append((nr, nc))
        if (rows - 1, cols - 1) in seen:
            return level

from heapq import heappop, heappush

def floodgate_path(grid):
    rows, cols = len(grid), len(grid[0])
    best = [[float('inf')] * cols for _ in range(rows)]
    best[0][0] = grid[0][0]
    heap = [(grid[0][0], 0, 0)]
    while heap:
        level, r, c = heappop(heap)
        if level > best[r][c]:
            continue
        if r == rows - 1 and c == cols - 1:
            return level
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                candidate = max(level, grid[nr][nc])
                if candidate < best[nr][nc]:
                    best[nr][nc] = candidate
                    heappush(heap, (candidate, nr, nc))

def floor_tracker(operations):
    stack, results = [], []
    for op in operations:
        if op[0] == 'push':
            stack.append(op[1])
        elif op[0] == 'pop':
            results.append(stack.pop())
        elif op[0] == 'top':
            results.append(stack[-1])
        else:
            results.append(min(stack))
    return results

def floor_tracker(operations):
    values, minimums, results = [], [], []
    for op in operations:
        if op[0] == 'push':
            value = op[1]
            values.append(value)
            minimums.append(min(minimums[-1], value) if minimums else value)
        elif op[0] == 'pop':
            minimums.pop()
            results.append(values.pop())
        elif op[0] == 'top':
            results.append(values[-1])
        else:
            results.append(minimums[-1])
    return results

def fragile_links(hubs, links):
    def clusters(skip):
        parent, size = list(range(hubs)), [1] * hubs
        count = hubs
        def find(node):
            while parent[node] != node:
                parent[node] = parent[parent[node]]
                node = parent[node]
            return node
        for edge, (a, b) in enumerate(links):
            if edge == skip:
                continue
            ra, rb = find(a), find(b)
            if ra != rb:
                if size[ra] < size[rb]:
                    ra, rb = rb, ra
                parent[rb] = ra
                size[ra] += size[rb]
                count -= 1
        return count
    base = clusters(-1)
    return sorted([min(a, b), max(a, b)] for edge, (a, b) in enumerate(links)
                  if clusters(edge) > base)

def fragile_links(hubs, links):
    adjacent = [[] for _ in range(hubs)]
    for edge, (a, b) in enumerate(links):
        adjacent[a].append((b, edge))
        adjacent[b].append((a, edge))
    order, low = [-1] * hubs, [0] * hubs
    bridges, clock = [], 0
    def dfs(node, via):
        nonlocal clock
        order[node] = low[node] = clock
        clock += 1
        for other, edge in adjacent[node]:
            if edge == via:
                continue
            if order[other] == -1:
                dfs(other, edge)
                low[node] = min(low[node], low[other])
                if low[other] > order[node]:
                    bridges.append([min(node, other), max(node, other)])
            else:
                low[node] = min(low[node], order[other])
    for hub in range(hubs):
        if order[hub] == -1:
            dfs(hub, -1)
    return sorted(bridges)

def fuel_stretch(fuel, target):
    best = 0
    for start in range(len(fuel)):
        total = 0
        for end in range(start, len(fuel)):
            total += fuel[end]
            if total >= target:
                if best == 0 or end - start + 1 < best:
                    best = end - start + 1
                break
    return best

def fuel_stretch(fuel, target):
    best, total, left = float('inf'), 0, 0
    for right, value in enumerate(fuel):
        total += value
        while total >= target:
            best = min(best, right - left + 1)
            total -= fuel[left]
            left += 1
    return 0 if best == float('inf') else best

def glyph_order(words):
    before = []
    for x in range(len(words)):
        for y in range(x + 1, len(words)):
            a, b = words[x], words[y]
            i = 0
            while i < min(len(a), len(b)) and a[i] == b[i]:
                i += 1
            if i == min(len(a), len(b)):
                if len(a) > len(b):
                    return ''
            else:
                before.append((a[i], b[i]))
    remaining = set(''.join(words))
    order = []
    while remaining:
        free = sorted(g for g in remaining
                      if not any(q == g and p in remaining for p, q in before))
        if not free:
            return ''
        order.append(free[0])
        remaining.remove(free[0])
    return ''.join(order)

def glyph_order(words):
    glyphs = set(''.join(words))
    after = {glyph: set() for glyph in glyphs}
    indegree = {glyph: 0 for glyph in glyphs}
    for a, b in zip(words, words[1:]):
        i = 0
        while i < min(len(a), len(b)) and a[i] == b[i]:
            i += 1
        if i == min(len(a), len(b)):
            if len(a) > len(b):
                return ''
        elif b[i] not in after[a[i]]:
            after[a[i]].add(b[i])
            indegree[b[i]] += 1
    ready = sorted(glyph for glyph in glyphs if indegree[glyph] == 0)
    order = []
    while ready:
        glyph = ready.pop(0)
        order.append(glyph)
        for following in after[glyph]:
            indegree[following] -= 1
            if indegree[following] == 0:
                ready.append(following)
                ready.sort()
    return ''.join(order) if len(order) == len(glyphs) else ''

def grid_rescue_hops(grid):
    rows, cols = len(grid), len(grid[0])
    distance = [[float('inf')] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                distance[r][c] = 0
            elif grid[r][c] == 'T':
                target = (r, c)
    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '#':
                    continue
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and distance[nr][nc] + 1 < distance[r][c]:
                        distance[r][c] = distance[nr][nc] + 1
                        changed = True
    best = distance[target[0]][target[1]]
    return -1 if best == float('inf') else best

from collections import deque

def grid_rescue_hops(grid):
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
    distance, queue = {start: 0}, deque([start])
    while queue:
        r, c = queue.popleft()
        if grid[r][c] == 'T':
            return distance[(r, c)]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in distance:
                distance[(nr, nc)] = distance[(r, c)] + 1
                queue.append((nr, nc))
    return -1

def grid_turn(matrix):
    n = len(matrix)
    return [[matrix[n - 1 - c][r] for c in range(n)] for r in range(n)]

def grid_turn(matrix):
    result = [row.copy() for row in matrix]
    for r in range(len(result)):
        for c in range(r + 1, len(result)):
            result[r][c], result[c][r] = result[c][r], result[r][c]
    for row in result:
        row.reverse()
    return result

def grove_harvest(tree):

    if not tree:
        return 0
    values, left, right = [tree[0]], [-1], [-1]
    index = 1
    node = 0
    while node < len(values) and index < len(tree):
        for children in (left, right):
            if index < len(tree):
                entry = tree[index]
                index += 1
                if entry is not None:
                    children[node] = len(values)
                    values.append(entry)
                    left.append(-1)
                    right.append(-1)
        node += 1

    best = 0
    for root in range(len(values)):
        walked, stack, at = [], [], root
        while at != -1 or stack:
            while at != -1:
                stack.append(at)
                at = left[at]
            at = stack.pop()
            walked.append(values[at])
            at = right[at]
        if all(walked[i - 1] < walked[i] for i in range(1, len(walked))):
            best = max(best, sum(walked))
    return best

def grove_harvest(tree):

    if not tree:
        return 0
    values, left, right = [tree[0]], [-1], [-1]
    index = 1
    node = 0
    while node < len(values) and index < len(tree):
        for children in (left, right):
            if index < len(tree):
                entry = tree[index]
                index += 1
                if entry is not None:
                    children[node] = len(values)
                    values.append(entry)
                    left.append(-1)
                    right.append(-1)
        node += 1

    best = 0
    def visit(node):
        nonlocal best
        if node == -1:
            return True, 0, float('inf'), float('-inf')
        a_ok, a_total, a_low, a_high = visit(left[node])
        b_ok, b_total, b_low, b_high = visit(right[node])
        if not a_ok or not b_ok or a_high >= values[node] or b_low <= values[node]:
            return False, 0, float('-inf'), float('inf')
        total = a_total + b_total + values[node]
        best = max(best, total)
        return True, total, min(a_low, values[node]), max(b_high, values[node])
    visit(0)
    return best

def gutter_capacity(heights):
    water = 0
    for i in range(len(heights)):
        left_wall = right_wall = 0
        for j in range(i + 1):
            left_wall = max(left_wall, heights[j])
        for j in range(i, len(heights)):
            right_wall = max(right_wall, heights[j])
        water += min(left_wall, right_wall) - heights[i]
    return water

def gutter_capacity(heights):
    n = len(heights)
    left_wall, right_wall = [0] * n, [0] * n
    for i in range(n):
        left_wall[i] = max(left_wall[i - 1] if i else 0, heights[i])
    for i in range(n - 1, -1, -1):
        right_wall[i] = max(right_wall[i + 1] if i + 1 < n else 0, heights[i])
    return sum(min(left_wall[i], right_wall[i]) - heights[i] for i in range(n))

def gutter_capacity(heights):
    left, right = 0, len(heights) - 1
    left_wall = right_wall = water = 0
    while left < right:
        if heights[left] < heights[right]:
            left_wall = max(left_wall, heights[left])
            water += left_wall - heights[left]
            left += 1
        else:
            right_wall = max(right_wall, heights[right])
            water += right_wall - heights[right]
            right -= 1
    return water
